window.VO = [{"id":"s01","text":"This Bengaluru traffic jam has no cause.","at":1.1,"t0":0.55,"t1":3.135},{"id":"s02","text":"Follow it to the front: no accident, no signal, not even a pothole.","at":6.97,"t0":3.485,"t1":7.82},{"id":"s03","text":"In two thousand eight, scientists in Japan made a jam out of nothing.","at":16.74,"t0":8.37,"t1":12.46},{"id":"s04","text":"Twenty-two cars, one circle, one rule: keep a steady speed.","at":25.62,"t0":12.81,"t1":16.44},{"id":"s05","text":"Then one driver slowed down. Just a little.","at":33.78,"t0":16.89,"t1":19.445},{"id":"s06","text":"The one behind reacted a beat late and braked harder. The next, harder still, until someone stopped.","at":39.69,"t0":19.845,"t1":26.045},{"id":"s07","text":"And the jam moved backwards, about as fast as a bicycle.","at":53.29,"t0":26.645,"t1":30.125},{"id":"s08","text":"The driver who started it never knew.","at":61.45,"t0":30.725,"t1":32.74},{"id":"s09","text":"That's the root cause: not the road. It's us, braking a beat too late.","at":66.38,"t0":33.19,"t1":37.275},{"id":"s10","text":"In two thousand eighteen, one self-driving car on a ring like this held a steady speed.","at":75.55,"t0":37.775,"t1":42.98},{"id":"s11","text":"The waves faded.","at":86.76,"t0":43.38,"t1":44.47},{"id":"s12","text":"So leave a gap. You could be the one who ends a jam.","at":90.14,"t0":45.07,"t1":48.245},{"id":"s13","text":"Or the one who starts it.","at":97.59,"t0":48.795,"t1":50.315}];
